using System.Text.Json;
using Aion.GameServer.Dataholders.RetailNpc;

namespace Aion.GameServer.Tests;

/// <summary>
/// Fixed vectors from the independently audited frozen USA source extraction. This is
/// an opt-in static artifact test, not a native runtime fixture or activation approval.
/// </summary>
public sealed class RetailNpcPilotSourceTests
{
    private const string DatasetId = "33dfd001439620a102ccfca9b30765578efa88acb6f561f8c116ce8d98873335";
    private const string OutputManifestSha = "036c316db96dcb1d50ccd2b55ef7b472afff9be557ea10c385cc22369d49b0cd";

    [SkippableFact]
    public async Task EveryPilotSourceVectorMatchesItsPinnedDatasetWithoutActivation()
    {
        string? directory = Environment.GetEnvironmentVariable("AION_RETAIL_NPC_STATIC_DATASET");
        Skip.If(string.IsNullOrWhiteSpace(directory), "Set AION_RETAIL_NPC_STATIC_DATASET to an immutable frozen USA generation; source evidence only");
        using var vectors = JsonDocument.Parse(PilotVectors);
        var wanted = vectors.RootElement.EnumerateArray().ToDictionary(x => x.GetProperty("id").GetInt32(), x => x.GetProperty("name").GetString()!);
        var dataset = await RetailNpcDatasetReader.LoadAsync(new(directory!, DatasetId, OutputManifestSha, wanted));
        Assert.Equal(25, dataset.Profiles.Count);
        Assert.Equal(63287, dataset.CoverageCount);
        Assert.Equal(117, dataset.IdentityBlockerCount);
        Assert.False(dataset.FixtureVerified);
        Assert.False(dataset.ActivationReady);
        foreach (var vector in vectors.RootElement.EnumerateArray())
        {
            var profile = dataset.Profiles[vector.GetProperty("id").GetInt32()];
            Assert.Equal(vector.GetProperty("name").GetString(), profile.Devname);
            foreach (var field in vector.GetProperty("root_fields").EnumerateObject())
                Assert.Equal(field.Value.EnumerateArray().Select(x => x.GetString()), profile.GetRawRootField(field.Name).RawValues);
            Assert.Equal(RetailNpcSourcePresence.Absent, profile.GetRawRootField("stat_ratio").Presence);
            Assert.False(profile.GetRawRootField("stat_ratio").DefaultApplied);
            Assert.Equal(vector.GetProperty("raw_sha256").GetString(), profile.SourceProvenance.GetProperty("raw_sha256").GetString());
            Assert.Equal(vector.GetProperty("semantic_sha256").GetString(), profile.SourceProvenance.GetProperty("semantic_sha256").GetString());
            var attack = Assert.Single(profile.OrderedLists.GetProperty("attacks").GetProperty("entries").EnumerateArray());
            foreach (var field in vector.GetProperty("attack_fields").EnumerateObject())
                Assert.Equal(field.Value.EnumerateArray().Select(x => x.GetString()), attack.GetProperty("projected_fields").GetProperty(field.Name).GetProperty("raw_values").EnumerateArray().Select(x => x.GetString()));
            Assert.Equal(vector.GetProperty("range_float32_bits").GetString(), attack.GetProperty("projected_fields").GetProperty("attack_range").GetProperty("float32_bits_hex").GetString());
            Assert.Equal(vector.GetProperty("skill_ids").EnumerateArray().Select(x => x.GetInt32()), profile.SkillBindings.EnumerateArray().Select(x => x.GetProperty("supported48_id").GetInt32()));
            Assert.Equal(vector.GetProperty("skill_names").EnumerateArray().Select(x => x.GetString()), profile.SkillBindings.EnumerateArray().Select(x => x.GetProperty("name").GetString()));
            Assert.All(profile.SkillBindings.EnumerateArray(), skill => Assert.Equal("dual_join_agrees_static_only", skill.GetProperty("status").GetString()));
            Assert.False(profile.FixtureVerified);
            Assert.False(profile.ActivationReady);
        }
    }

